<?php
/**
 * Pianissimo server configuration.
 *
 * Do not edit this file for your own installation: copy the keys you want to change
 * into server/config.local.php (git-ignored), e.g.
 *
 *   <?php return [
 *     'db_dsn'  => 'mysql:host=127.0.0.1;dbname=pianissimo;charset=utf8mb4',
 *     'db_user' => 'pianissimo',
 *     'db_pass' => 'a-strong-password',
 *   ];
 */
declare(strict_types=1);

$defaults = [
    // SQLite needs no setup; the file is created on first use (server/data is not web-accessible).
    'db_dsn' => 'sqlite:' . (getenv('PIANISSIMO_DB') ?: __DIR__ . '/data/pianissimo.sqlite'),
    'db_user' => null,
    'db_pass' => null,

    'session_name' => 'pianissimo_sid',
    'session_days' => 30,

    // limits
    'max_score_bytes' => 2 * 1024 * 1024,
    'max_scores_per_user' => 500,
    'auth_attempts_per_15min' => 10,

    // show exception messages in API errors (never enable in production)
    'debug' => (bool) getenv('PIANISSIMO_DEBUG'),
];

$local = is_file(__DIR__ . '/config.local.php') ? require __DIR__ . '/config.local.php' : [];
return array_merge($defaults, is_array($local) ? $local : []);
